// Method: PopupMenu::set_item_shortcut
static JSValue js_PopupMenu_set_item_shortcut(JSContext* ctx, JSValueConst this_val, int argc, JSValueConst* argv) {
    if (argc < 1) {
        return JS_ThrowTypeError(ctx, "PopupMenu.set_item_shortcut: missing handle argument");
    }

    int64_t handle;
    if (JS_ToInt64(ctx, &handle, argv[0]) < 0) {
        return JS_ThrowTypeError(ctx, "PopupMenu.set_item_shortcut: invalid handle");
    }

    QuickJSContext* qjs_ctx = get_qjs_ctx(ctx);
    if (!qjs_ctx || !qjs_ctx->get_object_registry()) {
        return JS_ThrowInternalError(ctx, "Context not initialized");
    }

    Object* obj = qjs_ctx->get_object_registry()->get_object(handle);
    if (!obj) {
        return JS_ThrowTypeError(ctx, "PopupMenu.set_item_shortcut: invalid or freed object");
    }

    PopupMenu* typed_obj = Object::cast_to<PopupMenu>(obj);
    if (!typed_obj) {
        return JS_ThrowTypeError(ctx, "PopupMenu.set_item_shortcut: object is not a PopupMenu");
    }

    // Argument count check (excluding handle) - only required args
    if (argc < 3) {
        return JS_ThrowTypeError(ctx, "PopupMenu.set_item_shortcut: expected at least 2 arguments, got %d", argc - 1);
    }

    // Convert arguments
    int64_t arg_index; JS_ToInt64(ctx, &arg_index, argv[1]);
    Ref<Shortcut> arg_shortcut;
    if (JS_IsNumber(argv[2])) {
        // Direct handle (unwrapped by JS proxy)
        int64_t h_shortcut; JS_ToInt64(ctx, &h_shortcut, argv[2]);
        Object* obj_shortcut = qjs_ctx->get_object_registry()->get_object(h_shortcut);
        arg_shortcut = Ref<Shortcut>(Object::cast_to<Shortcut>(obj_shortcut));
    } else {
        // Object with __handle property
        JSValue jh_shortcut = JS_GetPropertyStr(ctx, argv[2], "__handle");
        if (!JS_IsUndefined(jh_shortcut)) {
            int64_t h_shortcut; JS_ToInt64(ctx, &h_shortcut, jh_shortcut);
            Object* obj_shortcut = qjs_ctx->get_object_registry()->get_object(h_shortcut);
            arg_shortcut = Ref<Shortcut>(Object::cast_to<Shortcut>(obj_shortcut));
        }
        JS_FreeValue(ctx, jh_shortcut);
    }
    // Optional argument: global (default: false)
    bool arg_global = false;
    if (argc > 3) {
        // Override default with provided value
        arg_global = JS_ToBool(ctx, argv[3]);
    }

    typed_obj->set_item_shortcut(arg_index, arg_shortcut, arg_global);
    return JS_UNDEFINED;
}

